solution.code:
import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 昇順に並べて、短い 2 本の和と最長の 1 本を比べる
const [a, b, c] = input[0].split(" ").map(Number).sort((x, y) => x - y);
console.log(a + b > c ? "Yes" : "No");
